// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title IoTDeviceRegistry - Cross-service authentication for IoT firmware updates
/// @notice Manages device credentials and firmware update authorization
contract IoTDeviceRegistry {
    struct DeviceCredential {
        bytes32 deviceId;
        bytes32 credentialHash;
        uint256 lastAuthTimestamp;
        uint8 failedAttempts;
        bool isLocked;
        address authorizedService;
    }

    struct AuthSession {
        bytes32 sessionToken;
        uint256 expiresAt;
        address serviceEndpoint;
        bool isValid;
    }

    mapping(bytes32 => DeviceCredential) public devices;
    mapping(bytes32 => AuthSession) public sessions;
    mapping(address => bool) public trustedServices;
    mapping(bytes32 => uint256) private _nonceTracker;

    uint8 public constant MAX_FAILED_ATTEMPTS = 5;
    uint256 public constant LOCKOUT_DURATION = 1 hours;
    uint256 public constant SESSION_DURATION = 15 minutes;
    uint256 public constant RATE_LIMIT_WINDOW = 60;

    address public immutable owner;
    uint256 private _globalNonce;

    event DeviceAuthenticated(bytes32 indexed deviceId, address service);
    event DeviceLocked(bytes32 indexed deviceId);
    event CredentialRotated(bytes32 indexed deviceId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyTrustedService() {
        require(trustedServices[msg.sender], "Untrusted service");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerDevice(
        bytes32 deviceId,
        bytes32 credentialHash,
        address authorizedService
    ) external onlyOwner {
        require(devices[deviceId].deviceId == bytes32(0), "Device exists");
        require(trustedServices[authorizedService], "Service not trusted");

        devices[deviceId] = DeviceCredential({
            deviceId: deviceId,
            credentialHash: credentialHash,
            lastAuthTimestamp: 0,
            failedAttempts: 0,
            isLocked: false,
            authorizedService: authorizedService
        });
    }

    function addTrustedService(address service) external onlyOwner {
        trustedServices[service] = true;
    }

    /// @notice Cross-service authentication - validates device credential against stored hash
    /// @dev Uses commit-reveal pattern with nonce to prevent replay
    function authenticateDevice(
        bytes32 deviceId,
        bytes32 credential,
        uint256 nonce
    ) external onlyTrustedService returns (bytes32 sessionToken) {
        DeviceCredential storage device = devices[deviceId];
        require(device.deviceId != bytes32(0), "Device not found");

        // Check lockout status
        if (device.isLocked) {
            if (block.timestamp - device.lastAuthTimestamp < LOCKOUT_DURATION) {
                revert("Device locked");
            }
            // Auto-unlock after lockout duration
            device.isLocked = false;
            device.failedAttempts = 0;
        }

        // Verify nonce freshness
        require(nonce > _nonceTracker[deviceId], "Stale nonce");
        _nonceTracker[deviceId] = nonce;

        // Rate limiting check
        require(
            block.timestamp - device.lastAuthTimestamp >= RATE_LIMIT_WINDOW,
            "Rate limited"
        );

        // Compute expected hash: H(credential || deviceId || authorizedService)
        bytes32 computedHash = keccak256(
            abi.encodePacked(credential, deviceId, device.authorizedService)
        );

        // Credential verification with cross-service binding
        if (computedHash != device.credentialHash) {
            device.failedAttempts += 1;
            device.lastAuthTimestamp = block.timestamp;

            if (device.failedAttempts >= MAX_FAILED_ATTEMPTS) {
                device.isLocked = true;
                emit DeviceLocked(deviceId);
            }
            revert("Invalid credential");
        }

        // Authentication successful - reset counter and create session
        device.failedAttempts = 0;
        device.lastAuthTimestamp = block.timestamp;

        // Generate session token
        sessionToken = keccak256(
            abi.encodePacked(
                deviceId,
                block.timestamp,
                msg.sender,
                ++_globalNonce
            )
        );

        sessions[sessionToken] = AuthSession({
            sessionToken: sessionToken,
            expiresAt: block.timestamp + SESSION_DURATION,
            serviceEndpoint: msg.sender,
            isValid: true
        });

        emit DeviceAuthenticated(deviceId, msg.sender);
        return sessionToken;
    }

    /// @notice Allows any trusted service to attempt authentication on behalf of a device
    /// @dev Cross-service credential forwarding for federated IoT networks
    function crossServiceAuth(
        bytes32 deviceId,
        bytes32 credential,
        uint256 nonce,
        address targetService
    ) external onlyTrustedService returns (bytes32 sessionToken) {
        DeviceCredential storage device = devices[deviceId];
        require(device.deviceId != bytes32(0), "Device not found");
        require(trustedServices[targetService], "Target not trusted");

        // Cross-service auth: the calling service authenticates on behalf of device
        // The credential hash is computed against the CALLING service, not the device's bound service
        bytes32 computedHash = keccak256(
            abi.encodePacked(credential, deviceId, msg.sender)
        );

        // If calling service matches device's authorized service, use standard path
        if (msg.sender == device.authorizedService) {
            return this.authenticateDevice(deviceId, credential, nonce);
        }

        // Cross-service path: verify against device's stored credential
        // NOTE: This recomputes with the device's authorizedService for binding
        bytes32 boundHash = keccak256(
            abi.encodePacked(credential, deviceId, device.authorizedService)
        );

        if (boundHash != device.credentialHash) {
            // Failed auth from cross-service doesn't increment device lockout counter
            // to prevent denial-of-service via credential stuffing from other services
            revert("Cross-service auth failed");
        }

        // Nonce check for cross-service
        require(nonce > _nonceTracker[deviceId], "Stale nonce");
        _nonceTracker[deviceId] = nonce;

        device.lastAuthTimestamp = block.timestamp;

        sessionToken = keccak256(
            abi.encodePacked(deviceId, block.timestamp, targetService, ++_globalNonce)
        );

        sessions[sessionToken] = AuthSession({
            sessionToken: sessionToken,
            expiresAt: block.timestamp + SESSION_DURATION,
            serviceEndpoint: targetService,
            isValid: true
        });

        emit DeviceAuthenticated(deviceId, targetService);
        return sessionToken;
    }

    function rotateCredential(
        bytes32 deviceId,
        bytes32 newCredentialHash,
        bytes32 activeSessionToken
    ) external onlyTrustedService {
        require(sessions[activeSessionToken].isValid, "Invalid session");
        require(sessions[activeSessionToken].expiresAt > block.timestamp, "Session expired");
        require(sessions[activeSessionToken].serviceEndpoint == msg.sender, "Wrong service");

        devices[deviceId].credentialHash = newCredentialHash;
        emit CredentialRotated(deviceId);
    }

    function invalidateSession(bytes32 sessionToken) external {
        require(
            sessions[sessionToken].serviceEndpoint == msg.sender || msg.sender == owner,
            "Unauthorized"
        );
        sessions[sessionToken].isValid = false;
    }
}
